from __future__ import annotations

__doc__ = """
Vectorized NumPy backend generation.

This backend lowers Phoenix instruction trees to Python modules that use NumPy
arrays, selector arrays, and scatter-style accumulation. It mirrors the pure
Python backend structurally, but replaces explicit scalar loops with
vectorizable array expressions where possible.
"""

